# Keep Arabic display equations ordered and unbroken; spoken scripts remove isolates.
import re
ids=[f'M{m}-L0{i}' for m in [14,15] for i in range(1,5)]
for id in ids:
 for locale in LOCALES[:3]:
  f=ROOT/f'src/lib/technical-education/lessons/{id}__{locale}.json'
  def iso(v):
   if isinstance(v,str):return re.sub(r'\d+(?:\s*[−×=+]\s*\d+)+',lambda m:'\u2066'+m.group().replace(' ','\u00a0')+'\u2069',v)
   if isinstance(v,list):return[iso(x) for x in v]
   if isinstance(v,dict):return{k:iso(x) for k,x in v.items()}
   return v
  f.write_text(json.dumps(iso(json.loads(f.read_text())),ensure_ascii=False,indent=2)+'\n')
